package com.yeshoda.medical.controller; import com.yeshoda.medical.dto.AppointmentRequest; import com.yeshoda.medical.model.Appointment; import com.yeshoda.medical.service.AppointmentService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/appointments") public class AppointmentController {private final AppointmentService s;public AppointmentController(AppointmentService s){this.s=s;} @PostMapping public Appointment book(@RequestBody AppointmentRequest r){return s.book(r);} @GetMapping("/patient/{id}") public List<Appointment> patient(@PathVariable Long id){return s.byPatient(id);} @PutMapping("/{id}/cancel") public void cancel(@PathVariable Long id){s.cancel(id);}}
